        /// <summary>
        /// Get list actions of Controller
        /// </summary>
        /// <typeparam name="T">Controller</typeparam>
        /// <returns></returns>
        protected static List<string> GetActionListByController<T>()
        {
            var listAction = new List<string>();

            Type t = typeof(T);
            MethodInfo[] mi = t.GetMethods();
            foreach (MethodInfo m in mi)
            {
                if (m.IsPublic)
                    if (m.ReturnParameter != null && typeof(ActionResult).IsAssignableFrom(m.ReturnParameter.ParameterType))
                    {
                        listAction.Add(m.Name);
                    }
            }


            return listAction;

        }

        /// <summary>
        /// Ensures that ExecuteCore() is called.
        /// </summary>
        protected override bool DisableAsyncSupport
        {
            get { return true; }
        }

        protected override void ExecuteCore()
        {
            string cultureName = UserSession.Current.Language;
            if (string.IsNullOrEmpty(cultureName))
            {
                cultureName = "en-US"; // default
                UserSession.Current.Language = cultureName;
            }

            // Modify current thread's cultures
            Thread.CurrentThread.CurrentCulture = new CultureInfo(cultureName);
            Thread.CurrentThread.CurrentUICulture = Thread.CurrentThread.CurrentCulture;

            System.Globalization.CultureInfo def = System.Globalization.CultureInfo.CreateSpecificCulture("en-US");

            System.Threading.Thread.CurrentThread.CurrentCulture.DateTimeFormat = def.DateTimeFormat;
            System.Threading.Thread.CurrentThread.CurrentCulture.NumberFormat = def.NumberFormat;

            base.ExecuteCore();
        }

        protected DateTime[] ReportDateTimeRange
        {
            get
            {
                var request = System.Web.HttpContext.Current.Request;
                string rptmrange = request.QueryString["rptmrange"];
                if (string.IsNullOrEmpty(rptmrange))
                {
                    string url = request.Url.AbsolutePath;
                    return ReportTimer.GetReportTimeRange(url);
                }

                var timeRange = (ReportTimeRangeType)(int.Parse(rptmrange));
                return ReportTimer.GetReportTimeRange(timeRange);
            }
        }

        private void ValidateSecurityCode(ActionExecutingContext filterContext)
        {
            string redirectURL = SecurityCodeChecker.GetRedirectUrl();
            if (redirectURL != null)
            {
                if (Request.IsAjaxRequest())
                {
                    throw new SecurityException();
                }

                filterContext.Result = new RedirectResult(redirectURL);
            }
        }
